#!/usr/bin/env node
/**
 * Regenerates CHANGELOG.md from this repository's GitHub Releases.
 *
 * The release notes are the source of truth -- they are what a user reaching
 * this action from the Marketplace actually reads. Hand-maintaining a second
 * copy guarantees the two drift, and a changelog that lags the releases is the
 * same silent-omission failure this action exists to prevent, in documentation
 * form.
 *
 * Committing the generated file is still worth it: GitHub Releases are mutable
 * and their edits leave no record, whereas this file lands in the commit graph
 * next to the code it describes -- which matters for the sort of team that
 * pins actions by SHA and audits what it runs.
 *
 * Run `npm run changelog` after publishing a release, then open a pull request.
 */
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const REPO = "DigiCatalyst-Systems/dependabot-risk";
const OUT = new URL("../CHANGELOG.md", import.meta.url);

const releases = JSON.parse(
	execFileSync("gh", ["api", `repos/${REPO}/releases`, "--paginate"], {
		encoding: "utf8",
		maxBuffer: 32 * 1024 * 1024,
	})
)
	.filter((r) => !r.draft)
	.sort((a, b) => (a.published_at < b.published_at ? 1 : -1));

if (releases.length === 0) throw new Error("No published releases found.");

const day = (iso) => iso.slice(0, 10);

/** Release bodies are authored as Markdown; normalise only what would render wrong. */
const clean = (body) => (body ?? "").replace(/\r\n/g, "\n").trim();

const sections = releases.map((r) => {
	const title = r.name && r.name !== r.tag_name ? ` — ${r.name.replace(/^v[\d.]+\s*—\s*/, "")}` : "";
	const pre = r.prerelease ? " *(prerelease)*" : "";
	return [
		`## [${r.tag_name}](${r.html_url}) — ${day(r.published_at)}${title}${pre}`,
		"",
		clean(r.body) || "_No release notes._",
	].join("\n");
});

writeFileSync(
	OUT,
	[
		"# Changelog",
		"",
		"<!-- Generated by `npm run changelog` from GitHub Releases. Do not edit by hand. -->",
		"",
		`Every released version of this action, newest first, mirrored from`,
		`[GitHub Releases](https://github.com/${REPO}/releases).`,
		"",
		"The `v1` tag always points at the newest `v1.x` release, so `@v1` picks up",
		"everything below without a change on your side. Pin a commit SHA instead if",
		"you want to choose when that happens.",
		"",
		"---",
		"",
		sections.join("\n\n---\n\n"),
		"",
	].join("\n"),
	"utf8"
);

console.log(`Wrote CHANGELOG.md — ${releases.length} release(s), newest ${releases[0].tag_name}.`);
